float4 shade(float2 pos, float px) {
  float2 sz = size();
  float y = pos.y / sz.y;
  float3 c = lerp(srgb_to_linear(float3(0.050, 0.058, 0.092)), srgb_to_linear(float3(0.016, 0.018, 0.027)),
                  smoothstep(-0.05, 1.05, y));
  float2 q = (pos - float2(param(0), param(1))) / sz.y;
  c += srgb_to_linear(float3(0.22, 0.28, 0.62)) * 0.5 * exp(-dot(q, q) / 0.32);
  float2 r = (pos - float2(param(2), param(3))) / sz.y;
  c += srgb_to_linear(float3(1.0, 0.52, 0.30)) * 0.16 * exp(-dot(r, r) / 0.06);
  return float4(c * param(4), 1.0);
}
